class FirebaseAuthForm{constructor(){this.loginForm=document.getElementById("loginForm");this.signupForm=document.getElementById("signupForm");this.loginFormElement=document.getElementById("loginFormElement");this.signupFormElement=document.getElementById("signupFormElement");this.switchToSignup=document.getElementById("switchToSignup");this.switchToLogin=document.getElementById("switchToLogin");this.init()}init(){this.switchToSignup.addEventListener("click",e=>{e.preventDefault();this.switchForms("signup")});this.switchToLogin.addEventListener("click",e=>{e.preventDefault();this.switchForms("login")});this.loginFormElement.addEventListener("submit",e=>this.handleLoginSubmit(e));this.signupFormElement.addEventListener("submit",e=>this.handleSignupSubmit(e));this.setupPasswordToggles();const signupPassword=document.getElementById("signupPassword");signupPassword.addEventListener("input",e=>this.updatePasswordStrength(e.target.value));this.setupRealTimeValidation()}switchForms(formType){if(formType==="signup"){this.loginForm.classList.remove("active");this.signupForm.classList.add("active");this.signupFormElement.reset();this.clearAllErrors()}else{this.signupForm.classList.remove("active");this.loginForm.classList.add("active");this.loginFormElement.reset();this.clearAllErrors()}}setupPasswordToggles(){const toggles=document.querySelectorAll(".password-toggle");toggles.forEach(toggle=>{toggle.addEventListener("click",e=>{e.preventDefault();const targetId=toggle.getAttribute("data-target");const input=document.getElementById(targetId);const isPassword=input.type==="password";input.type=isPassword?"text":"password";toggle.textContent=isPassword?"🙈":"👁️"})})}setupRealTimeValidation(){document.getElementById("loginEmail").addEventListener("blur",e=>{this.validateEmail(e.target.value,"loginEmailError",e.target)});document.getElementById("loginPassword").addEventListener("blur",e=>{this.validateLoginPassword(e.target.value,"loginPasswordError",e.target)});document.getElementById("signupName").addEventListener("blur",e=>{this.validateName(e.target.value,"signupNameError",e.target)});document.getElementById("signupEmail").addEventListener("blur",e=>{this.validateEmail(e.target.value,"signupEmailError",e.target)});document.getElementById("signupPassword").addEventListener("blur",e=>{this.validateSignupPassword(e.target.value,"signupPasswordError",e.target)});document.getElementById("signupConfirmPassword").addEventListener("blur",e=>{this.validateConfirmPassword(e.target.value,"signupConfirmPasswordError",e.target)})}validateEmail(email,errorId,inputElement){const errorElement=document.getElementById(errorId);const emailRegex=/^[^\s@]+@[^\s@]+\.[^\s@]+$/;if(!email.trim()){errorElement.textContent="Email is required";inputElement.classList.add("error");return false}else if(!emailRegex.test(email)){errorElement.textContent="Please enter a valid email address";inputElement.classList.add("error");return false}else{errorElement.textContent="";inputElement.classList.remove("error");return true}}validateName(name,errorId,inputElement){const errorElement=document.getElementById(errorId);if(!name.trim()){errorElement.textContent="Full name is required";inputElement.classList.add("error");return false}else if(name.trim().length<2){errorElement.textContent="Name must be at least 2 characters";inputElement.classList.add("error");return false}else{errorElement.textContent="";inputElement.classList.remove("error");return true}}validateLoginPassword(password,errorId,inputElement){const errorElement=document.getElementById(errorId);if(!password){errorElement.textContent="Password is required";inputElement.classList.add("error");return false}else if(password.length<8){errorElement.textContent="Password must be at least 8 characters";inputElement.classList.add("error");return false}else{errorElement.textContent="";inputElement.classList.remove("error");return true}}validateSignupPassword(password,errorId,inputElement){const errorElement=document.getElementById(errorId);const hasUpperCase=/[A-Z]/.test(password);const hasLowerCase=/[a-z]/.test(password);const hasNumber=/[0-9]/.test(password);if(!password){errorElement.textContent="Password is required";inputElement.classList.add("error");return false}else if(password.length<8){errorElement.textContent="Password must be at least 8 characters";inputElement.classList.add("error");return false}else if(!hasUpperCase||!hasLowerCase||!hasNumber){errorElement.textContent="Password must contain uppercase, lowercase, and numbers";inputElement.classList.add("error");return false}else{errorElement.textContent="";inputElement.classList.remove("error");return true}}validateConfirmPassword(confirmPassword,errorId,inputElement){const errorElement=document.getElementById(errorId);const password=document.getElementById("signupPassword").value;if(!confirmPassword){errorElement.textContent="Please confirm your password";inputElement.classList.add("error");return false}else if(confirmPassword!==password){errorElement.textContent="Passwords do not match";inputElement.classList.add("error");return false}else{errorElement.textContent="";inputElement.classList.remove("error");return true}}updatePasswordStrength(password){const strengthElement=document.getElementById("passwordStrength");const strengthMeter=document.getElementById("strengthMeter");const strengthText=document.getElementById("strengthText");if(!password){strengthElement.classList.remove("visible");return}strengthElement.classList.add("visible");const hasUpperCase=/[A-Z]/.test(password);const hasLowerCase=/[a-z]/.test(password);const hasNumber=/[0-9]/.test(password);const hasSpecialChar=/[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?]/.test(password);const length=password.length;let strength=0;if(length>=8)strength++;if(hasUpperCase)strength++;if(hasLowerCase)strength++;if(hasNumber)strength++;if(hasSpecialChar)strength++;strengthMeter.classList.remove("weak","fair","strong");strengthText.classList.remove("weak","fair","strong");if(strength<=2){strengthMeter.classList.add("weak");strengthText.classList.add("weak");strengthText.textContent="Weak"}else if(strength<=3){strengthMeter.classList.add("fair");strengthText.classList.add("fair");strengthText.textContent="Fair"}else{strengthMeter.classList.add("strong");strengthText.classList.add("strong");strengthText.textContent="Strong"}}clearAllErrors(){const errorElements=document.querySelectorAll(".error-message");const inputElements=document.querySelectorAll(".form-group input");errorElements.forEach(el=>el.textContent="");inputElements.forEach(el=>el.classList.remove("error"))}async handleLoginSubmit(e){e.preventDefault();const email=document.getElementById("loginEmail").value.trim();const password=document.getElementById("loginPassword").value;const loginButton=this.loginFormElement.querySelector('button[type="submit"]');const emailValid=this.validateEmail(email,"loginEmailError",document.getElementById("loginEmail"));const passwordValid=this.validateLoginPassword(password,"loginPasswordError",document.getElementById("loginPassword"));if(!emailValid||!passwordValid){return}loginButton.disabled=true;loginButton.textContent="Signing in...";try{const userCredential=await firebase.auth().signInWithEmailAndPassword(email,password);const user=userCredential.user;localStorage.setItem("shopEaseUser",JSON.stringify({uid:user.uid,email:user.email,displayName:user.displayName||email.split("@")[0],loginTime:(new Date).toISOString()}));alert("Welcome back! You are now signed in.");window.location.href="index.html"}catch(error){this.handleAuthError(error,"login");loginButton.disabled=false;loginButton.textContent="Sign In"}}async handleSignupSubmit(e){e.preventDefault();const name=document.getElementById("signupName").value.trim();const email=document.getElementById("signupEmail").value.trim();const password=document.getElementById("signupPassword").value;const confirmPassword=document.getElementById("signupConfirmPassword").value;const signupButton=this.signupFormElement.querySelector('button[type="submit"]');const nameValid=this.validateName(name,"signupNameError",document.getElementById("signupName"));const emailValid=this.validateEmail(email,"signupEmailError",document.getElementById("signupEmail"));const passwordValid=this.validateSignupPassword(password,"signupPasswordError",document.getElementById("signupPassword"));const confirmPasswordValid=this.validateConfirmPassword(confirmPassword,"signupConfirmPasswordError",document.getElementById("signupConfirmPassword"));if(!nameValid||!emailValid||!passwordValid||!confirmPasswordValid){return}signupButton.disabled=true;signupButton.textContent="Creating Account...";try{const userCredential=await firebase.auth().createUserWithEmailAndPassword(email,password);const user=userCredential.user;await user.updateProfile({displayName:name});localStorage.setItem("shopEaseUser",JSON.stringify({uid:user.uid,email:user.email,displayName:name,createdAt:(new Date).toISOString()}));alert("Account created successfully! Welcome to ShopEase!");window.location.href="index.html"}catch(error){this.handleAuthError(error,"signup");signupButton.disabled=false;signupButton.textContent="Create Account"}}handleAuthError(error,formType){const errorCode=error.code;const errorMessage=error.message;let userMessage="An error occurred. Please try again.";let targetErrorId="";switch(errorCode){case"auth/email-already-in-use":userMessage="This email is already registered. Please sign in or use a different email.";targetErrorId=formType==="signup"?"signupEmailError":"loginEmailError";break;case"auth/invalid-email":userMessage="The email address is invalid. Please enter a valid email.";targetErrorId=formType==="signup"?"signupEmailError":"loginEmailError";break;case"auth/weak-password":userMessage="Your password is too weak. Please use a stronger password.";targetErrorId=formType==="signup"?"signupPasswordError":"loginPasswordError";break;case"auth/user-not-found":userMessage="No account found with this email. Please sign up first.";targetErrorId="loginEmailError";break;case"auth/wrong-password":userMessage="Incorrect password. Please try again.";targetErrorId="loginPasswordError";break;case"auth/too-many-requests":userMessage="Too many failed login attempts. Please try again later.";targetErrorId=formType==="signup"?"signupPasswordError":"loginPasswordError";break;default:userMessage=errorMessage||"An authentication error occurred."}if(targetErrorId){const errorElement=document.getElementById(targetErrorId);if(errorElement){errorElement.textContent=userMessage;const inputId=targetErrorId.replace("Error","");const inputElement=document.getElementById(inputId);if(inputElement){inputElement.classList.add("error")}}}else{alert(userMessage)}console.error("Firebase Auth Error:",errorCode,errorMessage)}}document.addEventListener("DOMContentLoaded",()=>{if(typeof firebase!=="undefined"&&firebase.auth){new FirebaseAuthForm}else{console.error("Firebase not loaded. Please check firebase-config.js")}});